def solve(n, a):
    a.sort(reverse=True)
    max_talks = 0
    pairs = []

    for i in range(n):
        for j in range(i+1, n):
            if a[i] > 0 and a[j] > 0:
                pairs.append((i+1, j+1))
                a[i] -= 1
                a[j] -= 1
                max_talks += 1

    return max_talks, pairs

def main():
    t = int(input())
    results = []

    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        talks, pair_list = solve(n, a)
        results.append((talks, pair_list))

    for talks, pair_list in results:
        print(talks)
        for i, j in pair_list:
            print(i, j)

main()
